TP.register({id:"lp4-g4",lp:4,grade:"4",mode:"baseline",nextGrade:"5th grade",build(E){const F=E.F;const STORY="Marisol had never seen snow until her family moved to Pine Hollow. On her first morning in the village, every roof was white and the air was so still she could hear her own breath. Cold air bit at her cheeks. Down the hill, the pond had frozen into a smooth gray mirror, and three kids were sliding across it on skates.\n\nKeisha from next door held out an old pair of skates. “Try them,” she said.\n\nMarisol laced them tight, stepped one blade onto the ice, and stopped. “I can’t,” she whispered. “I will fall.”\n\n“Everybody falls,” Keisha said. She dragged a wooden chair out onto the pond. “Push this. The chair will not let you tip over.”\n\nMarisol pushed the chair back and forth all morning. Gliding turned out to be the easy part. Stopping was her Achilles heel, and twice she slid off the ice into soft snow. She fell six times and got up six times. By the time the sun sank behind the pine trees, she let go of the chair and glided one slow lap alone.";const STORY_N=STORY.split(/\s+/).length;const TEXT_A={title:"A Blanket of Snow",body:"Fresh snow is not solid ice. It is made of tiny crystals with pockets of air trapped between them. All that trapped air is a poor path for heat, so ground under a deep layer of snow does not lose its warmth to the sky. On a night when the air above the snow drops far below freezing, the ground under a foot of snow can stay close to 32 degrees. Farmers sometimes call a deep snow a white blanket."};const TEXT_B={title:"Life Under the Snow",body:"Voles are small animals that look like round, short-tailed mice. They do not sleep through the winter. Instead they chew long tunnels in the space between the snow and the ground. In those tunnels they nibble grass stems, roots, and bark. The snow over their heads hides them, so an owl or a fox hunting above the snow has to listen for an animal it cannot see."};const FLAKE="Every snowflake starts high inside a cold cloud. Water vapor freezes onto a speck of dust, and a tiny crystal forms. The crystal has six sides, so arms grow out from six corners. As the crystal falls, it drifts through layers of air that are colder or wetter than the layer before. Each layer changes the way the arms grow. Because no two crystals fall along the exact same path, almost no two snowflakes end up the same shape.";const WORDS=["overcrowded","disagreement","thermometer","photograph","incorrectly","transportation","underground","reversible","geography","mismanage","unbrantable","misploration"];function storyHtml(small){return`<div class="passage${small?" sm":""}">${STORY.split(/\n\s*\n/).map(p=>`<p>${p}</p>`).join("")}</div>`}function twoTextsHtml(){return`<div class="texts"><article><h3>Text 1: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text 2: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function lookBackTexts(){return`<details class="look-back" open><summary>Look back at the two texts</summary>${twoTextsHtml()}</details>`}function lab(x,y,t,sz){return`<text x="${x}" y="${y}" font-size="${sz||26}" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${t}</text>`}function iceShapes(){return`<svg viewBox="0 0 780 185" width="780" role="img" aria-label="Four blocks of ice labeled A, B, C, and D"><g fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="4" stroke-linejoin="round"><polygon points="40,125 90,35 200,35 150,125"/><polygon points="240,125 240,45 320,45 370,125"/><polygon points="420,125 620,125 540,50"/><polygon points="670,125 670,40 760,125"/></g>${lab(120,172,"A")}${lab(303,172,"B")}${lab(520,172,"C")}${lab(700,172,"D")}</svg>`}const pills=(...w)=>`<div class="row center" style="margin-top:20px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const STOPS=[{id:1,title:"Snowshoe Word Flip",short:"Word Flip",parts:[{std:["RF.4.3"],kind:"words",wordPics:4,words:WORDS,n:12,dur:90,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading long words with prefixes, roots, and suffixes",key:["Read each word. unbrantable and misploration are made-up words: listen for the prefix, the middle, and the suffix (un-brant-a-ble, mis-plor-a-tion).","Watch for: prefixes (over-, dis-, in-, trans-, under-, re-, mis-), roots (therm, meter, photo, graph, geo, port), suffixes (-ed, -ment, -ly, -tion, -ible), and whether the student breaks long words into syllables or guesses from the first letters."]}]},{id:2,title:"Read in the Cabin",short:"Cabin Read",parts:[{std:["RF.4.4"],kind:"read",n:STORY_N,label:"words read correctly",dur:120,dir:"Read the story out loud. Use your best reading voice.",desc:`a ${STORY_N}-word grade-level story read aloud`,html:()=>storyHtml(false),key:[`${STORY_N} words. Time 1 minute and mark errors and self-corrections on your own copy.`,"Midyear grade 4 benchmark: about 120 words correct per minute (50th percentile, Hasbrouck and Tindal 2017 winter norms). The LP 1 game used the fall figure of 94, so expect the midyear bar to be higher.","Note pace and expression."]}]},{id:3,title:"Frozen Pond Questions",short:"Pond Qs",parts:[{title:"Prove It",std:["RL.4.1"],supfig:function(){return'<div style="text-align:center;margin:10px 0"><img alt="Three kids ice skating on a frozen pond at sunset. A girl in a purple hat pushes a wooden chair across the ice while a friend in a pink coat gives a thumbs up." src="data:image/webp;base64,'+window.TP_IMG1.wp3.pond4+'" style="max-width:100%;width:560px;height:auto;border-radius:14px"></div>'},dur:120,dir:"Answer out loud. Look back at the story for details.",desc:"questions answered with details and examples from a story",html:()=>storyHtml(true),qs:["How did Marisol feel when she put one blade on the ice? Give details from the story.","Why did Keisha drag a wooden chair onto the pond? Use a detail from the story.","How do you know Marisol kept trying even though skating was hard? Give examples from the story."],key:["Afraid, or sure she was going to fall. Details: she stopped after one blade touched the ice, she whispered “I can’t,” and she said “I will fall.” (RL.4.1, explicit)","So Marisol would have something to hold on to and push. Detail: Keisha says “Push this. The chair will not let you tip over.” (RL.4.1, inference)","She pushed the chair back and forth all morning, she fell six times and got up six times, she slid off the ice twice, and she still let go and glided a lap. (RL.4.1, inference)"]},{title:"Word Meanings",std:["RL.4.4"],supfig:function(){return'<div style="text-align:center;margin:10px 0"><img alt="Three kids ice skating on a frozen pond at sunset. A girl in a purple hat pushes a wooden chair across the ice while a friend in a pink coat gives a thumbs up." src="data:image/webp;base64,'+window.TP_IMG1.wp3.pond4+'" style="max-width:100%;width:560px;height:auto;border-radius:14px"></div>'},dur:75,dir:"Look back at the story. Answer out loud.",desc:"meanings of words and phrases in a story, including one from mythology",qs:["The story says “Stopping was her Achilles heel.” What does that mean? Who was Achilles?","What does the story mean when it says the pond “had frozen into a smooth gray mirror”?","What does “Cold air bit at her cheeks” mean?"],key:["Stopping was the one thing she was weak at. Achilles was a hero in Greek myths who was strong everywhere except his heel, so an Achilles heel means a person’s one weak spot. (RL.4.4, allusion to mythology)","The ice was so flat and shiny that it reflected the light like a mirror. The pond is not really a mirror. (RL.4.4)","The cold stung her skin. Nothing really bit her. (RL.4.4)"]}]},{id:4,title:"Under the Snow",short:"Snow Texts",parts:[{title:"Use the Text",std:["RI.4.1"],n:3,dur:145,dir:"Read both texts to yourself. Then answer out loud.",desc:"questions answered with details from informational texts",html:()=>twoTextsHtml(),qs:["What makes snow a poor path for heat? Give a detail from Text 1.","Why would a vole be easier for an owl to catch after the snow melts? Use details from Text 2.","Text 2 says voles do not sleep through the winter. Use details from Text 2 to say what a vole eats in winter and where it finds that food."],key:["The pockets of air trapped between the tiny crystals. Text 1 says fresh snow is not solid ice. (RI.4.1, explicit)","With the snow gone, nothing hides the vole, so the owl could see it instead of having to listen for an animal it cannot see. (RI.4.1, inference)","Grass stems, roots, and bark, nibbled in the long tunnels the vole chews in the space between the snow and the ground. Or: any two of the three foods named counts, as long as the tunnels under the snow are named as the place. Partial: the food named with nothing said about where it is found, or the tunnels named with no food, is approaching. (RI.4.1, explicit)"]},{title:"Put It Together",std:["RI.4.9"],n:3,dur:110,dir:"Think about both texts. Answer out loud.",desc:"putting together information from two texts on the same topic",qs:["Use both texts. Explain why living under the snow instead of on top of it helps a vole get through a cold winter.","One winter is bitterly cold but hardly any snow falls. Use a fact from Text 1 and a fact from Text 2. Give two different reasons that winter would be harder on a vole."],key:["Uses Text 2: the vole chews tunnels between the snow and the ground, eats grass stems, roots, and bark there, and the snow hides it from an owl or a fox. (RI.4.9)","Connects to Text 1: trapped air keeps the ground under deep snow near 32 degrees even when the air above is far below freezing, so the tunnels are much warmer than the open air. (RI.4.9)","Two reasons, one built on each text. From Text 1: with no deep snow there is no layer of trapped air over the ground, so the ground loses its warmth to the sky instead of staying close to 32 degrees, and the space the vole lives in would be far colder. From Text 2: the snow over the vole’s head is what hides it, so with almost no snow an owl or a fox could see it rather than having to listen for an animal it cannot see. Needs one reason from each text. Two reasons taken from the same text do not answer it. (RI.4.9)"]}]},{id:5,title:"Field Notes",parts:[{std:["W.4.8"],dur:120,dir:"Look back at the two texts. Write your notes on your paper and hold it up.",desc:"taking notes in their own words, sorting the notes, and listing sources",html:()=>`<p class="big" style="margin-top:0">You are gathering facts for a report about how deep snow changes winter for small animals.</p>${lookBackTexts()}`,qs:["Write two notes about snow and voles, one from each text. Keep them short and use your own words.","Sort your notes. Write a heading above each note: How Snow Works or Animals Under the Snow.","List your sources. Next to each note, write the title of the text it came from."],key:["Two short notes, one from each text, in the student’s own words and not copied sentences. Examples: trapped air keeps the ground warm; voles tunnel under snow and eat stems. (W.4.8: gathers information, takes notes, paraphrases)","Each note sits under the heading that fits. Text 1 facts (crystals, trapped air, ground near 32 degrees) go under How Snow Works. Text 2 facts (tunnels, nibbling stems and bark, hidden from owls) go under Animals Under the Snow. (W.4.8: categorizes)","Writes both titles, each next to the right note: A Blanket of Snow and Life Under the Snow. (W.4.8: lists sources)"]}]},{id:6,title:"Snowflake Listen",short:"Listen",parts:[{std:["SL.4.2"],n:3,label:"checks met",dur:90,dir:"Listen to your teacher read. Then tell it back in your own words.",desc:"paraphrasing a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${F.icon("snowflake",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about how a snowflake is made. Then tell it back in your own words.</p>`,read:FLAKE,key:["Tells the main idea: a snowflake grows from a crystal that forms on a speck of dust in a cold cloud. (SL.4.2)","Includes 2 or more key details: the crystal has six sides so arms grow from six corners; it falls through layers of colder or wetter air; each layer changes how the arms grow; no two fall the same path. (SL.4.2)","Uses their own words, not the passage word for word. (SL.4.2)"]}]},{id:7,title:"Shovel the Grammar",short:"Grammar",parts:[{std:["L.4.1"],dur:75,dir:"Say each sentence out loud the correct way.",desc:"spoken grammar items (relative pronouns, progressive tense, adjective order, fragments, confused words)",qs:["The sled ____ broke was my brother’s. (that or who)","Yesterday at noon I ____ the walk when the snow started again. (shovel)","Fix the order: a wool blue hat","Fix it so it is a whole sentence: Skated across the frozen pond.","The dog shook the snow off ____ back. (its or it’s)"],key:["that (L.4.1, relative pronoun)","was shoveling (L.4.1, progressive tense)","a blue wool hat (L.4.1, order of adjectives)","Adds a subject, such as: My cousin skated across the frozen pond. (L.4.1, fixing a fragment)","its (L.4.1, frequently confused words)"]}]},{id:8,title:"Warming Hut Report",short:"Report",parts:[{std:["SL.4.4"],n:4,label:"checks met",dur:90,dir:"Talk for about one minute. Speak clearly.",desc:"reporting on a topic out loud in an organized way with facts and details",html:()=>`<p class="big">Pick an animal you know something about. Report on how that animal finds food or stays safe. Tell me enough that I could tell someone else about it.</p>${pills("Name the animal","Main idea","Facts and details")}`,key:["Reports in an organized order, not jumping around (SL.4.4)","Gives facts that fit the animal and the question (SL.4.4)","Adds relevant, descriptive details that support the main idea (SL.4.4)","Speaks clearly at a pace you can follow (SL.4.4)"]}]},{id:9,title:"Pine Tree Count",short:"Place Value",parts:[{std:["4.NBT.A.1"],dur:90,dir:"Look at the number on the village sign. Answer out loud.",desc:"how a digit is worth 10 times what the same digit is worth one place to its right",fig:()=>`<p class="huge">8,800</p><p class="small" style="text-align:center;margin-top:0">pine trees in the village</p>`,qs:["In 8,800, how does the 8 in the thousands place compare to the 8 in the hundreds place?","A 3 in the tens place is worth 30. In which place would a 3 be worth 10 times as much. What would it be worth there?","True or silly: in 6,600 the 6 in the hundreds place is worth 10 times as much as the 6 in the thousands place. If it is silly, fix it.","Finish this: 5,000 is ____ times as much as 500."],key:["It is 10 times as much. 8,000 is 10 times 800. Partial: naming the two values with no comparison is approaching.","The hundreds place, where it would be worth 300. 300 is 10 times 30. Partial: naming the place with no value given is approaching.","Silly. It is the other way around: the 6 in the thousands place is worth 6,000, and 6,000 is 10 times the 600 in the hundreds place. Partial: saying it is silly with no fix given is approaching.","10. Partial: 100 counts two places instead of one and does not count."]}]},{id:10,title:"Snow Gauge Rounding",short:"Round It",parts:[{std:["4.NBT.A.3"],dur:75,dir:"Say each answer out loud.",desc:"rounding multi-digit numbers to a given place",qs:["Round 46,382 to the nearest thousand.","Round 46,382 to the nearest hundred.","Round 46,382 to the nearest ten thousand.","A plow drove 1,750 miles this winter. Round that to the nearest hundred miles."],key:["46,000. Partial: 47,000 rounds up when the hundreds digit is 3 and does not count.","46,400. Partial: 46,300 rounds down when the tens digit is 8 and does not count.","50,000. Partial: 40,000 rounds down when the thousands digit is 6 and does not count.","1,800 miles. Partial: 1,700 rounds down when the tens digit is 5 and does not count."]}]},{id:11,title:"Times as Many Sleds",short:"Times",parts:[{std:["4.OA.A.1"],dur:90,dir:"Say number 1 out loud. Write 2 and 3 on your paper and hold it up.",desc:"multiplication as a comparison (times as many)",qs:["48 = 6 × 8. Finish the sentence: 48 is ____ times as many as 8.","Write an equation for this: 45 is 9 times as many as 5.","Rosa shoveled 7 driveways. Theo shoveled 4 times as many driveways as Rosa. Write an equation and solve."],key:["6. The blank is 6 and only 6, because 48 is 6 groups of 8. Do not accept 8 here. (The sentence “48 is 8 times as many as 6” is also true, but it is a different sentence and not an answer to this one.) Partial: 8 answers a different sentence and does not count.","45 = 9 × 5. Or: 9 × 5 = 45 written the other way round counts equally.","4 × 7 = 28. Theo shoveled 28 driveways. Partial: the equation right with no number of driveways given is approaching."]}]},{id:12,title:"Rink Measures",short:"Measure",parts:[{title:"Units",std:["4.MD.A.1"],dur:90,dir:"Answer out loud. For the table, say both missing numbers.",desc:"sizes of measurement units, changing a larger unit to a smaller unit, and a two-column table",fig:()=>F.table(["Yards","Feet"],[[1,3],[2,"?"],[5,"?"]],{caption:"Snow fence"}),qs:["How many milliliters are in 5 liters?","How many seconds are in 4 minutes?","Which is longer: 1 meter or 150 centimeters?","3 pounds = ____ ounces","Finish the snow fence table. How many feet are in 2 yards? In 5 yards?"],key:["5,000 mL. Or: 5 × 1,000 = 5,000. Partial: 500 uses hundreds instead of thousands and does not count.","240 seconds. Or: 4 × 60 = 240. Partial: 240 with no unit named is approaching.","150 centimeters is longer (1 meter is only 100 centimeters). Partial: naming the 150 centimeters with no change into the same unit is approaching.","48 ounces. Or: 3 × 16 = 48. Partial: 48 with no unit named is approaching.","6 feet and 15 feet. Partial: one of the two rows right is approaching."]},{title:"Area and Perimeter",std:["4.MD.A.3"],n:3,dur:90,dir:"Solve on your paper. Show your work and hold it up.",desc:"area and perimeter of rectangles",fig:()=>F.row(F.rect(12,5,"m")),qs:["The skating rink is 12 meters long and 5 meters wide. Find the area and the perimeter.","A cabin porch covers 72 square feet. It is 8 feet wide. How long is it?"],key:["Area: 60 square meters (12 × 5). Partial: 60 with no square unit named is approaching.","Perimeter: 34 meters (12 + 12 + 5 + 5). Or: 2 × 12 + 2 × 5 = 34. Partial: 60 given as the perimeter is the area and does not count.","9 feet (72 ÷ 8). Partial: 9 with no unit named is approaching."]}]},{id:13,title:"Ice Blocks",short:"Shapes",parts:[{std:["4.G.A.2"],dur:75,dir:"Look at the blocks of ice. Answer out loud with the letters.",desc:"sorting shapes by parallel sides, perpendicular sides, and right angles",fig:()=>`<div class="figure">${iceShapes()}</div>`,qs:["Which blocks have parallel sides?","Which blocks have perpendicular sides?","Which block is a right triangle? How do you know?"],key:["A and B. Partial: one of the two blocks named is approaching.","B and D. Partial: one of the two blocks named is approaching.","D. It has one right angle (a square corner) where the two short sides meet. Partial: naming D with no reason is approaching."]}]},{id:14,title:"Cocoa Fractions",short:"Fractions",parts:[{title:"Equal Fractions",std:["4.NF.A.1"],n:3,dur:75,dir:"Look at the two bars. Answer out loud. Write your fractions on your paper.",desc:"explaining and making equivalent fractions",fig:()=>`<div class="figure"><div>${F.fracBar(4,3,{width:320})}<p class="fig-label">3/4</p></div><div>${F.fracBar(12,9,{width:320})}<p class="fig-label">9/12</p></div></div>`,qs:["Do these bars show the same amount? Explain using the number of parts and the size of the parts.","Write two fractions that are equal to 3/5."],key:["Yes, the same amount is shaded. Partial: saying yes with nothing said about the parts is approaching.","Explains: the second bar has 3 times as many parts, and each part is 3 times smaller, so the shaded amount is the same size. Partial: naming the number of parts with nothing said about their size is approaching.","Any two: 6/10, 9/15, 12/20, 15/25. Partial: one equal fraction given is approaching."]},{title:"Compare Fractions",std:["4.NF.A.2"],n:3,dur:95,dir:"Show your thinking on your paper and hold it up.",desc:"comparing fractions with different numerators and denominators",qs:["Would you rather have 2/5 of a mug of cocoa or 3/8 of a mug? Which one is more? Show how you know.","Use &gt;, &lt;, or =: 5/6 ____ 7/12","Which is greater: 3/4 of a mug or 5/6 of a mug? Show how you know."],key:["2/5 is more. Shows 16/40 and 15/40, or another valid reason. Either mug is a fine thing to pick, as long as the comparison is right. Partial: naming 2/5 with no reason is approaching.","5/6 &gt; 7/12. 5/6 is the same as 10/12, and 10/12 is more than 7/12. Partial: the right choice with the sign the wrong way round is approaching.","5/6. Shows 9/12 and 10/12, or another valid reason. Or: 3/4 is 1/4 short of a full mug and 5/6 is only 1/6 short, and a sixth is a smaller piece than a fourth, so 5/6 is nearer the top. Both are above 1/2, so a student who tries the 1/2 benchmark and finds it settles nothing is reasoning well. Partial: naming 5/6 with no reason is approaching. (4.NF.A.2)"]}]},{id:15,title:"Frozen Decimals",short:"Decimals",parts:[{title:"Fractions and Decimals",std:["4.NF.C.6"],n:3,dur:60,dir:"Write your answers on your paper and hold it up.",desc:"writing tenths and hundredths as decimals and fractions",fig:()=>`<div class="figure"><div>${F.gridRect(10,10,47,{cell:34})}<p class="fig-label">One whole pond</p></div></div>`,qs:["The shaded part of the pond is cleared for skating. What part of the grid is shaded? Write it as a fraction.","Write that same amount as a decimal.","Write 6/10 as a decimal."],key:["47/100 (4 full rows of 10, then 7 more squares). Partial: 47 given with no fraction form is approaching.","0.47. Or: 47/100 is 4 tenths and 7 hundredths, which is 0.47.","0.6. Or: 6/10 is 60/100, which is 0.60."]},{title:"Compare Decimals",std:["4.NF.C.7"],n:3,dur:60,dir:"Answer out loud. Tell how you know.",desc:"comparing decimals to hundredths",qs:["Which is greater: 0.7 or 0.68? How do you know?","Use &gt;, &lt;, or =: 0.09 ____ 0.9"],key:["0.7 is greater. Partial: naming 0.7 with no reason is approaching.","Reason: 0.7 is 70 hundredths and 0.68 is 68 hundredths, or uses a model. Partial: naming the hundredths with no comparison made is approaching.","0.09 &lt; 0.9. Partial: making 0.09 the greater one counts digits instead of places and does not count."]}]},{id:16,title:"Write by the Window",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Tell what you think and why"},std:["W.4.1","L.4.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">The village can build one new thing beside the frozen pond: a warming hut that serves hot cocoa, or a bigger skating rink. Which one should the village build? Write your opinion. Write 5 or 6 sentences.</p><ul class="qlist" style="margin-top:14px"><li>State your opinion</li><li>Give reasons with facts or details</li><li>Use linking words: another reason, for example, also</li><li>End with a concluding sentence</li></ul>`,key:["Introduces the topic and states an opinion (W.4.1)","Gives reasons supported by facts and details (W.4.1)","Links the opinion and the reasons with words like another reason, for example, also (W.4.1)","Ends with a concluding statement (W.4.1)","Complete sentences, no fragments or run-ons (L.4.1)"]},{alt:{group:"write",key:"facts",label:"Facts",icon:"🔎",hint:"Explain how snow helps small animals"},std:["W.4.2","L.4.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">How does deep snow help small animals get through a cold winter? Write to explain it. Use facts from the two texts. Write 5 or 6 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Introduce your topic</li><li>Give facts, details, or examples</li><li>Use linking words: for example, also, because</li><li>End with a concluding sentence</li></ul>${lookBackTexts()}`,key:["Introduces the topic clearly (W.4.2)","Develops the topic with facts, details, or examples from the texts, such as trapped air, warmer ground, tunnels, or hiding from owls (W.4.2)","Links ideas with words like for example, also, because, another (W.4.2)","Ends with a concluding statement (W.4.2)","Complete sentences, no fragments or run-ons (L.4.1)"]},{alt:{group:"write",key:"story",label:"Story",icon:"📖",hint:"Tell a real or made-up story"},std:["W.4.3","L.4.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">Write a story about a cold morning when someone tried something new and did not get it right the first time. It can be real or made up. Write 5 or 6 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Start by telling who is in the story and where they are</li><li>Tell what happens in order. Use words like at first, then, by the end</li><li>Add details: what people said, saw, or felt</li><li>Give your story an ending</li></ul>`,key:["Sets up the situation and introduces a narrator or characters (W.4.3)","Events unfold in a clear order, with transition words like at first, then, by the end (W.4.3)","Uses dialogue or description with concrete or sensory details (W.4.3)","Ends with a conclusion that follows from the events (W.4.3)","Complete sentences, no fragments or run-ons (L.4.1)"]}]},{id:17,title:"Pine and Deer",short:"Structures",parts:[{std:["4-LS1-1"],n:3,dur:75,dir:"Look at the two living things. Answer out loud or in writing.",desc:"arguing that named plant and animal structures do a job that supports survival, growth or reproduction",html:()=>`<p class="big">A pine stands at the edge of the village. A deer moves along the treeline below it.</p>
     <div class="figure">${F.icon("pine",104)}${F.icon("deer",104)}</div>
     <p class="big">The pine has thin needles instead of flat leaves. It has thick bark. It has cones that hold its seeds. The deer has a thick winter coat and long legs. It has a four part stomach inside its body.</p>`,qs:["Name the job of the pine's needles and the job of its cones.","Pick one deer structure from the list and build an argument for how it supports survival in a cold winter.","Thick bark is an outside structure of the pine. What does it protect the tree from?"],key:["Needles catch sunlight to make food, and their small narrow shape loses less water and lets snow slide off instead of piling up. Cones hold and protect the seeds, so they support reproduction. (4-LS1-1)","Thick coat: traps a layer of air that holds body heat in, so the deer loses less heat. Long legs: let it walk through deep snow to reach food. Four part stomach: lets it digest tough twigs and bark when nothing green is left. Any one, with a claim and a reason. (4-LS1-1)","Cold, drying wind, insects and damage, and it shields the living layer of wood just underneath. Protection of the living tissue is the idea. (4-LS1-1)"]},{std:["4-LS1-2"],n:3,dur:75,dir:"Read what happens, then answer. You may draw your model.",desc:"modelling the path from sense organ to brain to response in an animal",html:()=>`<p class="big">A deer is pulling bark from a fallen branch. A loose stone rolls down the slope above it. The deer lifts its head, swivels both ears toward the slope, stands still for a moment, then walks calmly into the trees.</p>
     <div class="figure">${F.icon("deer",104)}${F.icon("mountain",104)}</div>`,qs:["Which sense took in the information, and which body part took it in?","The deer stood still for a moment before it moved. What was its brain doing then?","Make a three step model of the path, from the stone rolling to the deer walking into the trees."],key:["Hearing, taken in by the ears. Swivelling the ears points them at the source, which is itself a response that collects better information. (4-LS1-2)","Processing the information: working out where the sound came from and what it meant, and choosing a response from several possible ones. (4-LS1-2)","The ears take in the sound, the brain processes it and chooses an action, the legs carry the action out. Missing the brain step is approaching, not proficient. (4-LS1-2)"]}]},{id:18,title:"The Road Cut",short:"Rock Layers",parts:[{std:["4-ESS1-1"],n:3,dur:90,dir:"Study the cut above the village. Answer out loud or in writing.",desc:"reading rock layers and the fossils in them as evidence of landscape change",html:()=>`<p class="big">A road was cut into the hillside above the village and left four layers showing. Layers stack with the newest on top.</p>
     <table class="bigTable"><tr><th>Layer</th><th>What the rock is like</th><th>Fossils in it</th></tr>
     <tr><td>top</td><td>loose stones and sand mixed together</td><td>pine cones and wood</td></tr>
     <tr><td>second</td><td>fine pale ash</td><td>leaf prints</td></tr>
     <tr><td>third</td><td>flat gray shale</td><td>fish and water plants</td></tr>
     <tr><td>bottom</td><td>sandstone with ripple marks</td><td>worm burrows</td></tr></table>`,qs:["Which layer has been there the longest? What in the chart tells you?","The third layer holds fish fossils. What was this hillside like when it formed?","Use the four layers in order to explain how this landscape changed over time."],key:["The bottom sandstone, because layers build upward and everything above landed on it later. (4-ESS1-1)","It was under water, a lake or a sea, deep and still enough for fine mud to settle and for fish and water plants to live. (4-ESS1-1)","Shallow rippled water laid down sand with worms in it, then deeper still water left mud with fish, then ash fell from a volcano over a landscape with leafy plants, then loose stones and sand built up where forest grows now. Any account reading the chart upward and naming the changes counts. (4-ESS1-1)"]},{std:["4-ESS2-1"],n:3,dur:75,dir:"Look at the measurements. Answer out loud or in writing.",desc:"using measurements to compare the rate of weathering and erosion under different conditions",html:()=>`<p class="big">The village set out four identical blocks of soft rock for one winter and weighed what was lost from each.</p>
     <table class="bigTable"><tr><th>Block</th><th>Where it sat</th><th>Weight lost over the winter</th></tr>
     <tr><td>1</td><td>in a dry shed</td><td>2 grams</td></tr>
     <tr><td>2</td><td>outside, soaked with water that froze and thawed each night</td><td>71 grams</td></tr>
     <tr><td>3</td><td>under the drip from the roof</td><td>38 grams</td></tr>
     <tr><td>4</td><td>outside in the wind, kept dry under a small cover</td><td>9 grams</td></tr></table>`,qs:["Which block lost the most? Name what was acting on it.","Water that freezes expands. Use that fact and the chart to explain block 2.","Which block is the one to compare the others against, and why is it needed?"],key:["Block 2, 71 grams. Water freezing and thawing again and again was acting on it, along with the water itself. (4-ESS2-1)","Water soaked into tiny cracks, then froze and pushed the cracks wider each night, then thawed and soaked deeper. Night after night this broke pieces off, which is why block 2 lost far more than any other. (4-ESS2-1)","Block 1 in the dry shed, which lost almost nothing. It shows how much the rock would lose with none of the weather acting on it, so the other numbers can be compared against it. (4-ESS2-1)"]}]},{id:19,title:"Snow on the Map",short:"Map Patterns",parts:[{std:["4-ESS2-2"],n:3,dur:90,dir:"Study the snow survey chart. Answer out loud or in writing.",desc:"interpreting map data to describe patterns in Earth's features",html:()=>`<p class="big">On the same day in winter, snow was measured at six survey points on a line running up and over the range from west to east.</p>
     <div class="figure">${F.icon("mountain",80)}${F.icon("snowflake",80)}${F.icon("pine",80)}</div>
     <table class="bigTable"><tr><th>Point</th><th>Height</th><th>Snow depth</th></tr>
     <tr><td>1 west foot</td><td>300 m</td><td>0 cm</td></tr>
     <tr><td>2</td><td>900 m</td><td>35 cm</td></tr>
     <tr><td>3</td><td>1,700 m</td><td>140 cm</td></tr>
     <tr><td>4 crest</td><td>2,600 m</td><td>310 cm</td></tr>
     <tr><td>5</td><td>1,900 m</td><td>95 cm</td></tr>
     <tr><td>6 east foot</td><td>1,300 m</td><td>20 cm</td></tr></table>`,qs:["Describe the pattern linking height and snow depth across all six points.","Point 5 and point 3 are close in height, but the snow depths are very different. Describe that difference using the numbers.","A seventh point is found at 2,200 m on the west side. Use the pattern to predict its snow depth and explain your reasoning."],key:["The higher the point, the deeper the snow. It rises from nothing at 300 meters to 310 centimeters at the 2,600 meter crest, then falls again going down the east side. (4-ESS2-2)","Point 3 at 1,700 meters has 140 centimeters and point 5 at 1,900 meters has only 95 centimeters, even though point 5 is higher. The west side gets more snow than the east side at the same height. (4-ESS2-2)","Somewhere between 140 and 310 centimeters, so around 200 to 250 centimeters, because it sits between points 3 and 4 on the same side of the range. The reasoning matters more than the number. (4-ESS2-2)"]},{std:["4-ESS3-2"],n:3,dur:95,dir:"Read the two plans. Answer out loud or in writing.",desc:"generating and comparing solutions that reduce the impact of a natural Earth process",html:()=>`<p class="big">Heavy snow piles on the flat roof of the village hall, and the beams groan under the weight. The village can do one thing this year.</p>
     <table class="bigTable"><tr><th>Plan</th><th>What it does</th><th>Cost and time</th><th>What it needs afterwards</th></tr>
     <tr><td>A: rebuild the roof with a steep pitch</td><td>snow slides off instead of piling up</td><td>high, a whole summer of work</td><td>nothing each winter, but a clear strip around the building</td></tr>
     <tr><td>B: add extra posts and beams under the flat roof</td><td>holds a much heavier load of snow</td><td>low, two weekends</td><td>someone must still shovel the roof in the deepest winters</td></tr></table>`,qs:["Name a third idea of your own for reducing the effect of heavy snow on the hall.","Compare plan A and plan B. Which would you choose. What in the chart supports that?","Which plan would you pick if the village had only two free weekends and very little money. Which if it had a whole summer and plenty of money? Say what made your answer change."],key:["Any workable idea: heat cables or a warm attic so snow melts off, a metal roof surface that snow slides off, a smaller second roof over the entrance, a schedule for clearing the roof after each storm, a rail that keeps sliding snow off the doorway. (4-ESS3-2)","Either plan, judged on the chart. Plan A ends the problem but costs a summer of work and leaves sliding snow to manage. Plan B is cheap and quick but leaves shovelling to do every deep winter. The reason from the chart is what is rated. (4-ESS3-2)","B for two weekends and little money, A for the summer and the money, with the cost and time column named as the thing that moved: the chart gives B as low cost and two weekends and A as high cost and a whole summer. What is rated is that the choice moves when the limits move, and that the student says which column it moved on. Or: a student who holds to A in both cases and argues that saving up for one summer beats shovelling every deep winter is reasoning well, as long as the trade is named. Partial: the same plan given for both sets of limits with no account of the change is approaching. (4-ESS3-2)"]}]},{id:20,title:"Heating the Village",short:"Energy Sources",parts:[{std:["4-ESS3-1"],n:3,dur:90,dir:"Study the chart. Answer out loud or in writing.",desc:"describing where energy and fuels come from and how their use affects the environment",html:()=>`<p class="big">Four ways the village heats its buildings and makes its electricity.</p>
     <table class="bigTable"><tr><th>Source</th><th>Natural resource behind it</th><th>Runs out?</th><th>One effect on the environment</th></tr>
     <tr><td>wood stoves</td><td>trees from the slope</td><td>yes, if cut faster than they grow</td><td>smoke in the valley air, fewer trees</td></tr>
     <tr><td>heating oil</td><td>oil pumped from underground</td><td>yes</td><td>gases into the air, risk of spills when trucked in</td></tr>
     <tr><td>small hydro turbine in the creek</td><td>moving water from rain and snowmelt</td><td>no, but the creek is low in late summer</td><td>changes the creek flow, can block fish</td></tr>
     <tr><td>solar panels on the hall roof</td><td>sunlight</td><td>no</td><td>little power on short snowy days, panels must be made</td></tr></table>`,qs:["Pick two rows and trace each one back to the natural resource it starts from.","Only one of these four is both renewable and reliable in deep winter here. Which one, and what in the chart makes the others unreliable or limited?","The village moves from oil to the creek turbine. Name one effect that gets smaller and one new effect that appears."],key:["Any two read correctly: wood from trees, heating oil from oil underground, the turbine from moving water fed by rain and snowmelt, the panels from sunlight. (4-ESS3-1)","The creek turbine, because the creek runs all winter from rain and snow. Panels give little power on short snowy days, wood runs out if cut too fast, and oil runs out and has to be trucked in. (4-ESS3-1)","Gases from burning oil, and the spill risk of trucking fuel in, both get smaller. New effects: the turbine changes the creek flow and can block fish, and in late summer the low creek may not run it. (4-ESS3-1)"]}]},{id:21,title:"Down the Sled Hill",short:"Speed",parts:[{std:["4-PS3-1"],n:3,dur:75,dir:"Look at the results. Answer out loud or in writing.",desc:"using evidence to explain how the speed of an object relates to its energy",html:()=>`<p class="big">The same loaded sled was let go from three heights on the hill and ran into a row of straw bales at the bottom. The bales were pushed along the snow.</p>
     <table class="bigTable"><tr><th>Start</th><th>Speed at the bottom</th><th>Bales pushed</th></tr>
     <tr><td>a third of the way up</td><td>3 meters each second</td><td>8 cm</td></tr>
     <tr><td>two thirds of the way up</td><td>5 meters each second</td><td>24 cm</td></tr>
     <tr><td>from the very top</td><td>7 meters each second</td><td>49 cm</td></tr></table>`,qs:["What happens to the distance the bales move as the sled's speed goes up?","Which run carried the most energy into the bales? Name the evidence.","Use the chart to explain the link between how fast something moves and how much energy it has."],key:["It grows, and by bigger steps each time: 8 cm, 24 cm, 49 cm. (4-PS3-1)","The run from the very top, at 7 meters each second, because it pushed the bales 49 cm, farther than either other run. (4-PS3-1)","The faster the sled, the more energy it has, shown by how far the same bales were pushed. Look for the claim with at least one pair of numbers behind it. (4-PS3-1)"]},{std:["4-PS3-3"],n:3,dur:75,dir:"Answer out loud or in writing. A prediction needs a reason, not the right answer.",desc:"asking a question and predicting the energy change in a collision",html:()=>`<p class="big">Two sleds sit on the flat below the hill. One is loaded with firewood and rolling slowly along the packed track. An empty sled is standing still in front of it.</p>
     <div class="figure">${F.icon("sled",96)}${F.icon("sled",96)}</div>`,qs:["Ask one question about this collision that a test could answer.","Predict what happens to the empty sled and to the loaded one.","Name two places the energy goes when the two sleds meet."],key:["Any testable question: how far does the empty sled slide, does it go farther on ice than on soft snow, does a faster push make a louder knock, what if both sleds are loaded. (4-PS3-3)","The empty sled is pushed forward and moves off. The loaded sled slows down, and may stop. Both halves make the full prediction. (4-PS3-3)","Any two of: into motion of the empty sled, into sound, into heating and scraping where they strike, into packing or spraying the snow. Energy moving from one sled to the other is the main idea. (4-PS3-3)"]}]},{id:22,title:"Energy Through the Village",short:"Transfer",parts:[{std:["4-PS3-2"],n:4,dur:75,dir:"For each observation, say how the energy traveled. Answer out loud or in writing.",desc:"matching observations to energy transferred by sound, light, heat or electric current",html:()=>`<p class="big">Four things noticed in the village on one cold evening.</p>
     <table class="bigTable"><tr><th></th><th>What was noticed</th></tr>
     <tr><td>1</td><td>The stove is lit and the whole room becomes warm, the far corner last.</td></tr>
     <tr><td>2</td><td>The hall bell is rung and people on the other side of the valley look up.</td></tr>
     <tr><td>3</td><td>A wire runs from the hall roof panels to the lamp by the door, and the lamp comes on.</td></tr>
     <tr><td>4</td><td>A lamp in an upstairs window makes a bright patch on the snow outside.</td></tr></table>`,qs:["How did the energy travel in observation 1?","How did it travel in observation 2?","How did it travel in observation 3?","How did it travel in observation 4?"],key:["By heat, out from the stove through the air and along the walls and floor to the far corner. (4-PS3-2)","By sound, through the air across the valley to everybody's ears. (4-PS3-2)","By an electric current, through the wire from the panels to the lamp, where it becomes light and heat. (4-PS3-2)","By light, out of the window and onto the snow. (4-PS3-2)"]},{std:["4-PS3-4"],n:3,dur:90,dir:"Draw your device and label it. Then answer out loud or in writing.",desc:"designing, testing and improving a device that converts energy from one form to another",html:()=>`<p class="big">The woodshed has no light and no wiring. Design a device that turns one kind of energy into light inside the shed. You may use a hand crank, a small generator, wire, a bulb, a mirror, a window, or a panel that takes in daylight.</p>
     <div class="figure">${F.icon("lamp",96)}${F.icon("snowflake",96)}</div>`,qs:["Draw and label your device. Show where the energy goes in and where the light comes out.","Name the kind of energy going in and the kind coming out.","You test it and the light lasts only a few seconds after you stop cranking. Name one change and say why it should help."],key:["Any labeled drawing with a path: a crank turning a small generator, wire, and a bulb; or daylight caught by a mirror or panel and sent into the shed. Labels and the path make it a design. (4-PS3-4)","Going in: motion from the crank, or light from outside. Coming out: light, and heat as well. Both forms named. (4-PS3-4)","Any change with a reason: add a small store such as a battery or capacitor so the light carries on, add a flywheel so the generator keeps spinning, use a bulb that needs less energy. A change with no reason is approaching. (4-PS3-4)"]}]},{id:23,title:"Sound, Snow Glare and Signals",short:"Waves",parts:[{std:["4-PS4-1"],n:3,dur:75,dir:"Look at the two drawings. Answer out loud or in writing.",desc:"using a wave model to describe amplitude and wavelength and the effect waves have on objects",html:()=>`<p class="big">The village drew the sound of the hall bell as a wave, once when it was struck gently and once when it was struck hard. The dotted line is silence.</p>
     <div class="figure"><svg viewBox="0 0 520 300" width="520" role="img" aria-label="Two waves drawn above one another with letters A and B marking parts of the first wave">
       <text x="10" y="18" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">struck gently</text>
       <line x1="20" y1="70" x2="500" y2="70" stroke="var(--line)" stroke-width="2" stroke-dasharray="6 6"/>
       <path d="M20 70 q30 -28 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0" fill="none" stroke="var(--sea)" stroke-width="5"/>
       <line x1="50" y1="70" x2="50" y2="56" stroke="var(--coral)" stroke-width="4"/>
       <text x="62" y="62" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">B</text>
       <line x1="20" y1="112" x2="140" y2="112" stroke="var(--coral)" stroke-width="4"/>
       <text x="80" y="134" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif" text-anchor="middle">A</text>
       <text x="10" y="186" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">struck hard</text>
       <line x1="20" y1="240" x2="500" y2="240" stroke="var(--line)" stroke-width="2" stroke-dasharray="6 6"/>
       <path d="M20 240 q30 -78 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0" fill="none" stroke="var(--sea)" stroke-width="5"/>
     </svg></div>`,qs:["Which letter marks the amplitude, and which marks the wavelength?","Which measurement changed when the bell was struck hard. What do you hear when it changes?","The window panes rattle when the bell is struck hard but not when it is struck gently. Explain that using the drawings."],key:["B marks the amplitude, the height from the flat line to the crest. A marks the wavelength, the distance from one crest to the next. (4-PS4-1)","The amplitude grew. A larger amplitude in a sound wave is heard as a louder sound. The wavelength stayed the same, so the note is the same pitch. (4-PS4-1)","A bigger amplitude carries more energy, and a wave with enough energy can make an object move. The hard strike sends enough energy to shake the panes; the gentle strike does not. (4-PS4-1)"]},{std:["4-PS4-2"],n:3,dur:75,dir:"Answer out loud or in writing. You may draw arrows.",desc:"modelling how light reflects from objects into the eye so the objects can be seen",html:()=>`<p class="big">On a bright day the snow outside the village is almost too bright to look at. Inside the shed with the door shut it is completely dark. A red mitten on the floor cannot be seen at all.</p>
     <div class="figure">${F.icon("mitten",96)}${F.icon("sun",96)}</div>`,qs:["Draw or tell the path of the light when someone outside sees the snow. Name each place it goes.","Why does snow look so much brighter than bare ground on the same day?","The mitten is on the shed floor in complete darkness. Why can it not be seen?"],key:["Light leaves the sun, travels to the snow, reflects off the snow, and travels into the eye. All three legs are needed. (4-PS4-2)","Snow reflects much more of the light that falls on it, so far more light reaches the eye from snow than from dark ground, which absorbs most of the light instead. (4-PS4-2)","No light is reaching it, so no light can reflect off it into an eye. An object has to send light to the eye to be seen, and in complete darkness there is none to send. (4-PS4-2)"]},{std:["4-PS4-3"],n:3,dur:75,dir:"Read the two systems. Answer out loud or in writing.",desc:"comparing two solutions that use patterns to send information",html:()=>`<p class="big">The two ends of the valley need three messages: the road is open, come to the hall, and send the sled.</p>
     <table class="bigTable"><tr><th>System</th><th>How a message is sent</th><th>Needs</th></tr>
     <tr><td>Lamp in the hall tower</td><td>one long shine, two short flashes, or three short flashes</td><td>darkness or dusk to be seen; no use in bright daylight or thick snowfall</td></tr>
     <tr><td>Bell in the hall tower</td><td>one ring, two rings, or a long roll of rings</td><td>carries across the valley in any light; muffled by heavy falling snow</td></tr></table>`,qs:["Say what the pattern is in each system.","It is noon and clear. Which system works, and what in the chart tells you?","Design a third system of your own for the same three messages, using neither a lamp nor a bell."],key:["In the lamp system the pattern is the number of flashes and whether a flash is long or short. In the bell system it is the number of rings and how long the ringing lasts. An agreed pattern standing for a message is what carries the information. (4-PS4-3)","The bell, because the lamp is no use in bright daylight while the bell carries across the valley in any light. (4-PS4-3)","Any pattern with three agreed signals: a flag raised to one of three heights, three shapes cut and hung on the tower, one, two or three smoke puffs, a colored panel turned to one of three faces, three agreed words on a radio. (4-PS4-3)"]}]},{id:24,title:"Keeping the Water Barrel Open",short:"Design",parts:[{std:["3-5-ETS1-1"],n:3,dur:60,dir:"Read the situation, then answer out loud or in writing.",desc:"defining a design problem with criteria for success and constraints",html:()=>`<p class="big">The barrel outside the kitchen door freezes over every night. In the morning nobody can draw water from it. The village has one afternoon, scrap boards, old blankets, a sheet of clear plastic, and no money.</p>
     <div class="figure">${F.icon("drop",88)}${F.icon("snowflake",88)}</div>`,qs:["State the problem in one sentence, in your own words.","Write two criteria that would tell the village the fix works.","Write two constraints from the situation."],key:["Something like: water in the barrel needs to stay liquid overnight so it can be used in the morning. A problem statement, not a solution. (3-5-ETS1-1)","Any two testable criteria: water can be drawn in the morning, no ice thicker than a thin skin, the barrel can still be filled and covered by one person, nothing has to be bought. (3-5-ETS1-1)","One afternoon, only scrap boards, blankets and clear plastic, no money. Any two. Listing a criterion here instead is approaching. (3-5-ETS1-1)"]},{std:["3-5-ETS1-2"],n:3,dur:75,dir:"Study the three designs. Answer out loud or in writing.",desc:"generating and comparing solutions against the criteria and constraints",html:()=>`<p class="big">Three fixes for the barrel.</p>
     <table class="bigTable"><tr><th>Fix</th><th>What it is</th><th>Materials</th><th>Build time</th></tr>
     <tr><td>1</td><td>wrap the barrel in old blankets and put a board lid on top</td><td>blankets, a board</td><td>short</td></tr>
     <tr><td>2</td><td>build a small box over the barrel with a clear plastic top facing the sun</td><td>scrap boards, clear plastic</td><td>most of the afternoon</td></tr>
     <tr><td>3</td><td>fit an electric heater on a timer in the water</td><td>a heater and cable to buy, and wiring</td><td>several days</td></tr></table>`,qs:["Which fix breaks a constraint? Name the constraint it breaks.","Compare fix 1 and fix 2 against the criteria. Which do you expect to keep the water liquid longer, and why?","Add a fourth idea of your own that fits the materials and the time."],key:["Fix 3. The heater and cable have to be bought and there is no money, and several days is longer than the one afternoon. (3-5-ETS1-2)","Either, argued from the criteria. Blankets slow heat from leaving but add none, so a long cold night can still freeze it. The clear box lets sunlight in during the day and traps that heat, so it both gains and holds heat. A student who says do both, blankets plus the box, is reasoning well. (3-5-ETS1-2)","Any idea in the materials on hand: sink the barrel into the ground where the soil is warmer, move it against the kitchen wall, paint it dark so it absorbs more sun, put a floating board on the water to slow the surface freezing, fill it with warm water in the evening. (3-5-ETS1-2)"]},{std:["3-5-ETS1-3"],n:3,dur:75,dir:"Answer out loud or in writing.",desc:"planning a fair test with controlled variables and naming a failure point",html:()=>`<p class="big">The village wants to find out whether the blanket wrap or the clear topped box keeps the water liquid longer. They have two barrels and a thermometer.</p>
     <div class="figure">${F.icon("thermometer",96)}${F.icon("drop",96)}</div>`,qs:["Plan the test. What will you measure, and when?","Name two things you must keep the same for both barrels so the test is fair.","Name one failure point: where your fix is most likely to stop working first."],key:["Measure the water temperature in each barrel at the same times, for example at dusk and again at dawn, and measure the thickness of any ice in the morning. Numbers, not impressions. (3-5-ETS1-3)","Any two: the same amount of water at the same starting temperature, the same night and weather, barrels of the same size and material, the same spot or two spots that get the same sun and wind, lids opened the same number of times. (3-5-ETS1-3)","Any sensible weak spot: blankets get wet and then lose their effect, the plastic top collects snow and blocks the sun, the lid freezes shut, a cold wind finds a gap at the bottom, the box fills with blown snow. (3-5-ETS1-3)"]}]},{id:25,title:"Over the Mountains",short:"Regions",parts:[{std:["HSS-4.1"],n:4,dur:90,dir:"Study the chart of four mountain passes and the land on either side. Answer out loud or in writing.",desc:"describing the physical and human geographic features that define places and regions in California",html:()=>`<p class="big">The Sierra Nevada runs most of the length of eastern California. Roads cross it at a few passes.</p>
     <div class="figure">${F.icon("mountain",80)}${F.icon("pine",80)}${F.icon("snowflake",80)}</div>
     <table class="bigTable"><tr><th>Pass</th><th>Height</th><th>Open all year?</th><th>What is on the west side</th><th>What is on the east side</th></tr>
     <tr><td>Donner</td><td>2,160 m</td><td>yes, cleared by plow</td><td>foothills, then the Central Valley</td><td>a high dry basin and a large lake</td></tr>
     <tr><td>Carson</td><td>2,610 m</td><td>usually, sometimes shut by storms</td><td>gold country canyons</td><td>dry valleys</td></tr>
     <tr><td>Tioga</td><td>3,031 m</td><td>no, shut by snow about half the year</td><td>deep granite valleys</td><td>desert basin and a salt lake</td></tr>
     <tr><td>Tehachapi</td><td>1,160 m</td><td>yes</td><td>the southern end of the Central Valley</td><td>the Mojave desert</td></tr></table>`,qs:["Which pass is the highest. What does the chart say happens to it in winter?","The east side of every pass is drier than the west side. Explain how the mountains cause that.","Name one physical feature and one human feature from the chart and say what makes each one that kind.","Why would a railway or a main highway choose Tehachapi rather than Tioga?"],key:["Tioga at 3,031 meters. It is shut by snow for about half the year. Partial: the pass named with nothing said about winter is approaching. (HSS-4.1)","Air blowing in from the ocean rises over the mountains, cools, and drops its rain and snow on the western slope. By the time it comes down the eastern side it has little moisture left, so the east is dry. Any version of this using the mountains as a barrier counts. Partial: saying the mountains block the rain with no account of the air rising and cooling is approaching. (HSS-4.1)","Physical: the passes, their heights, snow, deserts, lakes, granite valleys. Human: the roads, the snow plow clearing, the railway. Physical comes from nature, human is built or done by people. Partial: one of each named with no difference stated is approaching. (HSS-4.1)","Tehachapi is much lower, at 1,160 meters, and open all year, so trains and trucks can use it every day. Tioga is more than twice as high and shut half the year. Partial: naming Tehachapi with no numbers from the chart is approaching. (HSS-4.1)"]}]},{id:26,title:"Mountain Routes and the Rush",short:"California Past",parts:[{std:["HSS-4.2"],n:3,dur:205,dir:"Read the chart, then answer out loud or in writing.",desc:"describing the life and interactions among California's peoples from the first nations through the mission and rancho periods",html:()=>`<p class="big">Early California, inland and on the coast.</p>
     <table class="bigTable"><tr><th>People and period</th><th>Where they lived</th><th>Work, food and trade</th></tr>
     <tr><td>Miwok and Mono nations, for thousands of years</td><td>the Sierra foothills and both sides of the range</td><td>acorns, deer, fish and seeds; trade across the passes in summer, taking acorns and shell beads east and bringing back pine nuts, salt and obsidian</td></tr>
     <tr><td>Chumash nation, for thousands of years</td><td>the southern coast and the islands</td><td>fishing from plank canoes, shellfish, trade in shell beads used as money along the coast</td></tr>
     <tr><td>Spanish missions, 1769 onward</td><td>a line near the coast, linked by El Camino Real</td><td>wheat, corn, cattle and workshops, worked largely by Native Californians brought to live there</td></tr>
     <tr><td>Mexican ranchos, 1820s onward</td><td>coastal valleys and the edges of the Central Valley</td><td>cattle herds on granted land, hides and tallow traded to ships for goods</td></tr></table>
     <p class="big">Each of these nations had its own religious beliefs and its own ceremonies, shaped by the place it lived in, and they were not the same from nation to nation. Chumash ceremonies were led by trained specialists and included one that marked the turning of the sun in winter. The Miwok and Mono nations of the foothills danced in a large round earth covered ceremonial house, and both held a mourning ceremony each year for the people who had died since the last one.</p>
     <p class="big">The missions were founded by Franciscan missionaries sent from Spain to convert Native Californians to Christianity and to teach them Spanish crops and trades. Because the missions needed farmland, water and a supply road, they were built where those were, and the nations whose land that was lost the use of it.</p>`,qs:["The Miwok and Mono traded across the passes in summer. Why would the season matter for that trade?","Compare what the Chumash depended on with what the foothill nations depended on. Then name one difference between their ceremonies from the note. What explains the differences?","According to the note, what were the Franciscan missionaries there to do? The missions and ranchos were near the coast and the valley edges. They were there rather than high in the mountains. Give a geographic reason."],key:["The passes are blocked by deep snow for much of the year, so trade over them was only possible in the warm months. Snow depth, not choice, set the season. Partial: saying summer was easier with no account of the snow is approaching. (HSS-4.2)","The Chumash lived on the coast and islands, so they fished from canoes and gathered shellfish. The foothill nations lived among oaks and rivers, so acorns, deer and fish were what was there. On the ceremonies: the Chumash had trained specialists who led a ceremony marking the turning of the sun in winter, while the Miwok and Mono danced in a large round earth covered ceremonial house and held a yearly mourning ceremony. People used what their own place provided, and each nation kept its own beliefs rather than a shared religion. Both halves are needed for full credit. Partial: one half without the other is approaching, so the food comparison with nothing on the ceremonies sits there. (HSS-4.2)","The Franciscans were sent to convert Native Californians to Christianity and to teach them Spanish crops and trades. Geographic reason: the mountains are high, steep and snowbound much of the year, with no road and a short growing season, while cattle and wheat need open, lower, milder land with water, which the coastal valleys and valley edges have. Both halves are needed for full credit. Partial: one half without the other is approaching, so naming the purpose with no geographic reason sits there. (HSS-4.2)"]},{std:["HSS-4.3"],n:3,dur:90,dir:"Study the chart of routes, then answer out loud or in writing.",desc:"explaining the Gold Rush and the road to statehood, including who came and how",html:()=>`<p class="big">Three ways people reached California in 1849, and what happened once they arrived.</p>
     <table class="bigTable"><tr><th>Route</th><th>How long</th><th>Hardest part</th></tr>
     <tr><td>Overland by wagon across the plains and over the Sierra passes</td><td>about 5 months</td><td>crossing the dry basins, then the mountains before the snow closed the passes</td></tr>
     <tr><td>By ship around the southern tip of South America</td><td>5 to 8 months</td><td>storms at the tip, and months with no fresh food</td></tr>
     <tr><td>By ship to Panama, across by land, then by ship north</td><td>about 2 months</td><td>the land crossing, where many travellers fell ill</td></tr></table>`,qs:["Which route was fastest, and why did people still use the other two?","The overland travellers had to be over the passes before the snow. Connect that to what the passes chart shows about winter.","By 1850 California was a state, only two years after the gold was found. Explain how so many arrivals made statehood come so fast."],key:["Panama, about two months. People still used the others because the Panama crossing made many travellers ill, berths on the ships were costly and scarce, and families with wagons, tools and animals could only go overland. Partial: the fastest route named with no reason the others were used is approaching. (HSS-4.3)","High passes fill with snow and close for months, so a wagon arriving late could not cross until spring. Timing the journey to beat the snow was a matter of the geography, not of hurrying for its own sake. Partial: saying they had to hurry with no link to the passes closing is approaching. (HSS-4.3)","Tens of thousands of people arrived in a single year, so there were enough residents for statehood and an urgent need for courts, laws and a government where there was almost none. Delegates wrote a state constitution in 1849 and California was admitted in 1850. Partial: naming the population rise with nothing said about the need for government is approaching. (HSS-4.3)"]}]},{id:27,title:"Rails, Timber and Taking Part",short:"Government",parts:[{std:["HSS-4.4"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"tracing California's growth into an agricultural and industrial power since the 1850s",html:()=>`<p class="big">Building the railroad over the Sierra Nevada, and what followed.</p>
     <table class="bigTable"><tr><th>Fact</th><th>Detail</th></tr>
     <tr><td>The crews</td><td>Thousands of Chinese workers did much of the hardest building, cutting ledges and blasting tunnels through granite.</td></tr>
     <tr><td>The tunnels</td><td>Fifteen tunnels were cut near the summit. Crews worked through two very deep winters.</td></tr>
     <tr><td>Snow sheds</td><td>Long wooden roofs were built over miles of track so trains could run through winter snow.</td></tr>
     <tr><td>Finished 1869</td><td>The line joined California to the eastern states. Travel that took months took about a week.</td></tr>
     <tr><td>After</td><td>Timber mills, ice houses, orchards and whole towns grew along the line. California wheat and fruit were sold across the country.</td></tr></table>`,qs:["Why were snow sheds needed. What does that tell you about the geography the railroad crossed?","Travel time dropped from months to about a week. Name two effects that change would have on California business.","Name one group whose work built the railroad. One way the railroad changed where people lived."],key:["Deep snow buried the track every winter, so without roofs over it the line would be closed for months. The railroad had to cross a high range that gets very heavy snow. Partial: naming the snow with nothing said about the range it crossed is approaching. (HSS-4.4)","Any two: perishable goods such as fruit could be sold far away, tools and manufactured goods arrived cheaply, settlers and workers came in large numbers, mail and orders moved quickly so businesses could plan. Partial: one effect is approaching, and two effects asserted with no reasoning is approaching too. (HSS-4.4)","Chinese workers, who cut the ledges and tunnels through granite. Towns, mills and orchards grew along the line, so people settled where the railroad ran rather than only near the coast and the gold country. Partial: one of the two halves answered is approaching. (HSS-4.4)"]},{std:["HSS-4.5"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"explaining the structures, functions and powers of government and how people take part",html:()=>`<p class="big">Who decides, and how a person can take part.</p>
     <table class="bigTable"><tr><th>Level</th><th>Who is chosen by voters</th><th>How a resident can take part</th></tr>
     <tr><td>Local</td><td>mayor, city council, county supervisors, school board</td><td>speak at a council or board meeting, vote in local elections, sign a petition</td></tr>
     <tr><td>State</td><td>governor, state Assembly members, state senators</td><td>write to a representative, vote on state ballot measures</td></tr>
     <tr><td>Federal</td><td>the President, members of Congress</td><td>vote in national elections, write to a member of Congress</td></tr></table>`,qs:["Name the three branches of the federal government and say the job of each.","The village wants a plow to keep its road open. Which level of government would decide, and why?","Name two ways a resident can take part in a decision without being elected to anything."],key:["Congress makes the laws, the President and the departments carry them out, the federal courts decide what the laws mean in a case. The three jobs matter more than the names. Partial: two of the three jobs described is approaching. (HSS-4.5)","Local government, the city or county, because local road clearing is their responsibility and they set the local budget. A student who adds that a state highway would be the state's job is correct. Partial: the level right with no reason is approaching. (HSS-4.5)","Any two from the chart or sensible beyond it: speak at a council or board meeting, vote, sign a petition, write to a representative, serve on a local committee, attend a public hearing. Partial: one way named is approaching, and naming voting for a representative as the only way is approaching too. (HSS-4.5)"]}]}];const LEVELUPS={3:{id:"L3",lv:true,title:"Level Up: Quote It",std:["RL.5.1"],needs:["RL.4.1"],n:1,dir:"Read the exact words out loud.",html:()=>`${storyHtml(true)}<p class="big">Read me the exact words from the story that show Marisol was afraid to step onto the ice.</p>`,key:["Reads the exact line: “I can’t,” she whispered. “I will fall.” Also accept the exact words “stepped one blade onto the ice, and stopped.” (RL.5.1, quoting accurately)"]},7:{id:"L7",lv:true,title:"Level Up: Verb Tenses",std:["L.5.1"],needs:["L.4.1"],n:2,dir:"Say each sentence out loud the correct way.",html:()=>`<ol class="qlist"><li>By the time we reached the pond, the sun ____. (set)</li><li>Fix it: He laces his skates and stepped onto the ice.</li></ol>`,key:["had set (L.5.1, perfect tense)","He laced his skates and stepped onto the ice, or He laces his skates and steps onto the ice. (L.5.1, fixing a tense shift)"]},12:{id:"L12",lv:true,title:"Level Up: Fraction Area",std:["5.NF.B.4"],needs:["4.MD.A.3"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">A shoveled sled path is 8 feet long and 2/3 of a foot wide. What is its area?</p>`,key:["5 1/3 square feet: 8 × 2/3 = 16/3. (5.NF.B.4, multiplying a whole number by a fraction to find the area of a rectangle with a fractional side length)"]},14:{id:"L14",lv:true,title:"Level Up: Add Fractions",std:["5.NF.A.1"],needs:["4.NF.A.1"],n:1,dir:"Solve on your paper and hold it up.",html:()=>`<p class="huge" style="font-size:clamp(3rem,10vw,6rem)">1/4 + 2/5</p>`,key:["13/20 (5/20 + 8/20) (5.NF.A.1)"]}};const PASSAGE_STD=["RL.4.1","RL.4.4","RI.4.1","RI.4.9","RL.5.1","W.4.8","W.4.2"];const MULT_N=12,FRAC_DENS=[1,2,3,4,5,6,8,10,12];let multSel=[0,0],pvVal="",pvStop=null,fracOn={},gridOn=[0,0];function pvCols(st){return st&&st.std&&st.std.some(x=>x.indexOf("4.NF.C")===0)?{ints:["Tens","Ones"],decs:["Tenths","Hundredths"]}:{ints:["Hundred<br>thousands","Ten<br>thousands","Thousands","Hundreds","Tens","Ones"],decs:[]}}const STARTERS={opinion:["I think the village should build ____ because ____.","One reason is ____.","Another reason is ____.","For example, ____.","That is why ____."],facts:["Deep snow helps small animals by ____.","One fact is ____.","For example, ____.","Also, ____.","In conclusion, ____."],story:["It all started when ____.","At first, ____.","Then ____.","Right after that, ____.","By the end, ____."]};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvTable(st){const cols=pvCols(st),raw=pvVal.replace(/[^0-9.]/g,""),bits=raw.split("."),ip=bits[0]||"",dp=bits[1]||"";let h="<tr>";cols.ints.forEach(c=>h+=`<th>${c}</th>`);if(cols.decs.length){h+=`<th class="pt"></th>`;cols.decs.forEach(c=>h+=`<th>${c}</th>`)}h+="</tr><tr>";cols.ints.forEach((c,i)=>{const k=ip.length-(cols.ints.length-i);h+=`<td>${k>=0?ip[k]:""}</td>`});if(cols.decs.length){h+=`<td class="pt">.</td>`;cols.decs.forEach((c,i)=>h+=`<td>${dp[i]||""}</td>`)}return h+"</tr>"}function pvHtml(st){pvStop=st;return`<label class="pv-in">Type a number<input type="text" inputmode="decimal" id="pvInput" value="${pvVal}" autocomplete="off"></label><div class="tool-scroll"><table class="pv" id="pvTable">${pvTable(st)}</table></div>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${d>=10?" sm":""}${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}function gridHtml(){return`<div class="hg-wrap">`+[0,1].map(g=>{let c=`<div><div class="hg">`;for(let i=0;i<100;i++)c+=`<button class="hg-c${i<gridOn[g]?" on":""}" tabindex="-1" data-g="${g}" data-i="${i}" aria-label="Grid ${"AB"[g]} square ${i+1}"></button>`;return c+`</div><p class="fig-label" style="margin:4px 0 0">Grid ${"AB"[g]}</p></div>`}).join("")+`</div><p class="small">Each grid is 1 whole. Click a square to shade up to it. One full column is one tenth. Click the last shaded square to clear.</p>`}function measHtml(){const rows=[["Length",["1 meter = 100 centimeters","1 kilometer = 1,000 meters","1 foot = 12 inches","1 yard = 3 feet"]],["Weight and mass",["1 kilogram = 1,000 grams","1 pound = 16 ounces"]],["Liquid",["1 liter = 1,000 milliliters"]],["Time",["1 hour = 60 minutes","1 minute = 60 seconds"]]];return`<table class="meas">`+rows.map(r=>`<tr><th>${r[0]}</th></tr>`+r[1].map(x=>`<tr><td>${x}</td></tr>`).join("")).join("")+"</table>"}function formHtml(){return`<svg viewBox="0 0 320 170" width="320" role="img" aria-label="Rectangle with length and width labeled" style="display:block;margin:0 auto;max-width:100%;height:auto"><rect x="70" y="14" width="220" height="110" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="4"/><text x="180" y="154" text-anchor="middle" font-size="22" font-weight="700" fill="var(--ink)">length</text><text x="60" y="76" text-anchor="end" font-size="22" font-weight="700" fill="var(--ink)">width</text></svg>
  <p class="formula">Area = length × width</p><p class="small" style="margin-top:0">The space inside. Answer in square units.</p>
  <p class="formula">Perimeter = length + width + length + width</p><p class="small" style="margin-top:0">The distance around the outside.</p>`}const SENT_ALIAS={opinion:"W.4.1",facts:"W.4.2",story:"W.4.3","W.4.1":"opinion","W.4.2":"facts","W.4.3":"story"};function sentKey(st){const ps=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const pick=c=>!c?null:STARTERS[c]?c:SENT_ALIAS[c]&&STARTERS[SENT_ALIAS[c]]?SENT_ALIAS[c]:null;for(const p of ps){const a=pick(p.alt&&p.alt.key||p.wk||p.wt);if(a)return a;for(const c of p.std||[]){const k=pick(c);if(k)return k}}return null}function sentHtml(st){const k=sentKey(st);return`<ul class="starters">${(STARTERS[k]||STARTERS.opinion).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["4.OA.A.1","4.MD.A.1","4.MD.A.3","4.NF.A.1","4.NF.A.2","5.NF.B.4","5.NF.A.1"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const rr=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===rr&&multSel[1]===k?[0,0]:[rr,k];r()})},pv:{name:"Place value chart",std:["4.NBT.A.1","4.NBT.A.3","4.NF.C.6","4.NF.C.7"],html:pvHtml,bind:(b,r,st)=>{const inp=b.querySelector("#pvInput"),tb=b.querySelector("#pvTable");if(inp&&tb)inp.oninput=()=>{pvVal=inp.value.replace(/[^0-9.,]/g,"");tb.innerHTML=pvTable(st||pvStop)}}},frac:{name:"Fraction strips",std:["4.NF.A.1","4.NF.A.2","5.NF.A.1"],html:fracHtml,bind:(b,r)=>b.querySelectorAll(".fs-part").forEach(x=>x.onclick=()=>{const d=+x.dataset.d,k=+x.dataset.k;fracOn[d]=fracOn[d]===k+1?0:k+1;r()})},grid:{name:"Hundredths grids",std:["4.NF.C.6","4.NF.C.7"],html:gridHtml,bind:(b,r)=>b.querySelectorAll(".hg-c").forEach(x=>x.onclick=()=>{const g=+x.dataset.g,i=+x.dataset.i;gridOn[g]=gridOn[g]===i+1?0:i+1;r()})},meas:{name:"Measurement chart",std:["4.MD.A.1"],html:measHtml},form:{name:"Area and perimeter card",std:["4.MD.A.3"],html:formHtml},sent:{name:"Sentence starters",std:["W.4.1","W.4.2","W.4.3"],html:sentHtml}};const SUP_CAVEATS=[{t:"pv",std:["4.NBT.A.1"],msg:"The place value chart names the places, so the student does not have to recall place names. The ten times comparisons still need the student’s own reasoning."},{t:"frac",msg:"Fraction strips can show the answer. Rate on whether the student can explain what the strips show."},{t:"meas",msg:"4.MD.A.1 expects students to know the unit sizes. With the measurement chart, this stop shows converting only."},{t:"form",msg:"With the area and perimeter card, this stop shows the student can use the formulas, not that they remember them."},{t:"sent",msg:"Sentence starters supply the linking words and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
